        .when(focused, |card| {
            card.child(
                div()
                    .absolute()
                    .top_0()
                    .left_0()
                    .size_full()
                    .rounded(px(6.))
                    .border_2()
                    .border_color(accent),
            )
        });
    gpui_kit::TestSupportExt::test_support(card).into_any_element()
}

